/bin/bash -lc "python3 - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png')
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
g=cv2.medianBlur(g,7)
for p2 in [20,30,40,50,60]:
 cs=cv2.HoughCircles(g,cv2.HOUGH_GRADIENT,dp=1.2,minDist=60,param1=100,param2=p2,minRadius=15,maxRadius=100)
 print('p2',p2, None if cs is None else np.round(cs[0]).astype(int).tolist())
# Sobel bounding stats each coarse grid
edge=cv2.Canny(g,60,120)
print('edge fraction grid')
for gy in range(6):
 print([round(edge[gy*120:(gy+1)*120,gx*160:(gx+1)*160].mean()/255,3) for gx in range(8)])
# object pixel detailed row runs for saturated/low V along rows
hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV)
for y in [150,175,200,225,250,275,300,325,350,375,400,425]:
 for name,m in [('sat',(hsv[y,:,1]>80)),('dark',(hsv[y,:,2]<35)),('blue',((hsv[y,:,0]>90)&(hsv[y,:,0]<135)&(hsv[y,:,1]>70))),('yel',((hsv[y,:,0]>15)&(hsv[y,:,0]<45)&(hsv[y,:,1]>70)))]:
  z=np.flatnonzero(m)
  runs=[]
  if len(z):
   st=pr=z[0]
   for x in z[1:]:
    if x>pr+1:
     if pr-st>=2:runs.append((int(st),int(pr)))
     st=x
    pr=x
   if pr-st>=2:runs.append((int(st),int(pr)))
  if runs: print(y,name,runs)
PY"
